<script lang="ts">
	import { onMount } from 'svelte';
	import { supabase } from '#lib/supabase';
	import { Building2, Mail, MapPin, Phone, Plus, Search, UserRound, X } from '@lucide/svelte';
	let rows=$state<any[]>([]),loading=$state(true),error=$state(''),query=$state(''),showForm=$state(false),saving=$state(false);
	let form=$state({name:'',phone:'',email:'',address:'',city:'',notes:''});
	onMount(load);
	async function load(){loading=true;const {data,error:e}=await supabase.from('cb_records').select('*').eq('kind','customer').eq('deleted',false).order('updated_at',{ascending:false});if(e)error=e.message;else rows=data||[];loading=false}
	async function save(){if(!form.name.trim()){error='Müşteri adı gereklidir.';return}saving=true;const record={key:`c-${Date.now()}`,kind:'customer' as const,data:{...form,created_at:new Date().toISOString()},origin:'web' as const,deleted:false};const {error:e}=await supabase.from('cb_records').insert(record);if(e)error=e.message;else{form={name:'',phone:'',email:'',address:'',city:'',notes:''};showForm=false;await load()}saving=false}
	function filtered(){const q=query.toLocaleLowerCase('tr-TR');return rows.filter(r=>`${r.data?.name||''} ${r.data?.phone||''} ${r.data?.email||''}`.toLocaleLowerCase('tr-TR').includes(q))}
</script>
<svelte:head><title>Müşteriler | Tayfun Yapı</title></svelte:head>
<div class="page"><header><div><span>SATIŞ</span><h1>Müşteriler</h1><p>Müşteri kartları, iletişim bilgileri ve bağlı işler.</p></div><button onclick={() => (showForm = !showForm)}>
	{#if showForm}
		<X size={18}/>
	{:else}
		<Plus size={18}/>
	{/if}
	{showForm ? 'Kapat' : 'Müşteri Ekle'}
</button></header>
	{#if showForm}<section class="form"><h2>Yeni müşteri kartı</h2><div class="grid"><label>Ad soyad / firma<input bind:value={form.name} placeholder="Müşteri adı"/></label><label>Telefon<input bind:value={form.phone} placeholder="0 5xx xxx xx xx"/></label><label>E-posta<input type="email" bind:value={form.email}/></label><label>İl / ilçe<input bind:value={form.city} placeholder="Edremit, Balıkesir"/></label><label class="wide">Adres<input bind:value={form.address}/></label><label class="wide">Not<textarea bind:value={form.notes}></textarea></label></div>{#if error}<p class="error">{error}</p>{/if}<button class="save" onclick={save} disabled={saving}>{saving?'Kaydediliyor':'Müşteri kartını kaydet'}</button></section>{/if}
	<section class="summary"><div><UserRound/><span>Toplam müşteri<strong>{rows.length}</strong></span></div><div><Building2/><span>Aktif kayıt<strong>{rows.filter(r=>!r.deleted).length}</strong></span></div></section>
	<label class="search"><Search size={17}/><input bind:value={query} placeholder="Müşteri, telefon veya e-posta ara"/></label>
	{#if loading}<div class="state">Müşteriler yükleniyor...</div>{:else}<section class="cards">{#each filtered() as row}<article><div class="avatar">{(row.data?.name||'?').slice(0,2).toLocaleUpperCase('tr-TR')}</div><div class="name"><strong>{row.data?.name}</strong><span>{row.data?.city||'Konum eklenmedi'}</span></div><div class="details">{#if row.data?.phone}<a href={`tel:${row.data.phone}`}><Phone size={15}/>{row.data.phone}</a>{/if}{#if row.data?.email}<a href={`mailto:${row.data.email}`}><Mail size={15}/>{row.data.email}</a>{/if}{#if row.data?.address}<span><MapPin size={15}/>{row.data.address}</span>{/if}</div><a class="job" href={`/wizard?customer=${encodeURIComponent(row.data?.name||'')}`}>Yeni iş oluştur</a></article>{:else}<div class="state">Müşteri kaydı bulunamadı.</div>{/each}</section>{/if}
</div>
<style>
	.page{max-width:1380px;margin:auto;padding:30px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}header>div>span{font-size:10px;font-weight:800;color:#0f7c80;letter-spacing:1px}h1{font-size:28px;margin:2px 0}header p{margin:0;color:#78838e}header button,.save{height:40px;border:0;border-radius:6px;padding:0 14px;background:#ec942f;color:#fff;display:flex;align-items:center;gap:7px;font-weight:800;cursor:pointer}.form{padding:19px;background:#fff;border:1px solid #dfe4e8;border-radius:7px;margin-bottom:12px}.form h2{font-size:16px;margin:0 0 13px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:11px}.grid label{display:flex;flex-direction:column;gap:5px;font-size:11px;font-weight:700}.grid input,.grid textarea{border:1px solid #d6dde2;border-radius:5px;padding:10px;font:inherit}.grid textarea{min-height:65px}.wide{grid-column:1/-1}.save{margin:12px 0 0 auto;background:#0f7c80}.error{color:#b91c1c}.summary{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-bottom:10px}.summary>div{display:flex;align-items:center;gap:12px;padding:14px;background:#fff;border:1px solid #dfe4e8;border-radius:7px;color:#0f7c80}.summary span,.summary strong{display:block}.summary span{font-size:10px;color:#7c8791}.summary strong{font-size:19px;color:#26323b}.search{height:42px;display:flex;align-items:center;gap:8px;padding:0 12px;background:#fff;border:1px solid #d9dfe4;border-radius:6px;color:#7c8791;margin-bottom:10px}.search input{width:100%;border:0;outline:0;font:inherit}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{display:grid;grid-template-columns:45px 1fr;gap:10px;padding:15px;background:#fff;border:1px solid #dfe4e8;border-radius:7px}.avatar{width:43px;height:43px;display:grid;place-items:center;border-radius:6px;background:#173f49;color:#fff;font-weight:800}.name strong,.name span{display:block}.name span{font-size:11px;color:#7e8993;margin-top:2px}.details{grid-column:1/-1;display:grid;gap:7px;border-top:1px solid #edf0f2;padding-top:11px}.details a,.details span{display:flex;align-items:center;gap:7px;color:#66737e;text-decoration:none;font-size:11px}.job{grid-column:1/-1;text-align:center;padding:9px;background:#edf8f7;color:#0f7c80;border-radius:5px;text-decoration:none;font-weight:800;font-size:11px}.state{grid-column:1/-1;padding:60px;text-align:center;color:#81909a}
	@media(max-width:950px){.cards{grid-template-columns:1fr 1fr}}
	@media(max-width:650px){.page{padding:18px 12px 90px}header p{display:none}h1{font-size:23px}.grid{grid-template-columns:1fr}.wide{grid-column:auto}.cards{grid-template-columns:1fr}}
</style>
